// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(uint256 funding, uint8 depthSeed) public {
        // wide admissible domain: re-entry depth 2..3 and arbitrary funding
        vm.assume(funding >= 1000 && funding < 1e18);
        uint256 depth = 2 + bound(uint256(depthSeed), 0, 1); // guaranteed reentrancy
        vm.deal(address(c), funding);

        Attacker a = new Attacker(c, depth);
        bool ok;
        try a.go() { ok = true; } catch { ok = false; }

        // Rule: any bonus claim re-entered by the callee at least twice must revert
        // (the nonReentrant guard blocks the nested withdrawReward).
        assertTrue(depth < 2 || !ok);
    }
}

contract Attacker {
    Reentrancy_bonus c;
    uint256 maxDepth;
    uint256 depth;
    constructor(Reentrancy_bonus _c, uint256 _d) { c = _c; maxDepth = _d; }
    function go() external { c.getFirstWithdrawalBonus(address(this)); }
    receive() external payable {
        if (depth < maxDepth) {
            depth++;
            c.getFirstWithdrawalBonus(address(this));
        }
    }
}
